CREATE OR REPLACE FUNCTION public.start_life_activity(_type text DEFAULT NULL,_activity_id uuid DEFAULT NULL,_target_location_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; p public.character_positions; l public.locations; target public.locations; a public.activities; r public.life_rules; t timestamptz:=public.game_now(); acc public.accounts; s public.life_settings; j public.jobs; id uuid; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO c FROM public.characters WHERE id=cid FOR UPDATE; SELECT * INTO p FROM public.character_positions WHERE character_id=cid; SELECT * INTO l FROM public.locations WHERE id=p.location_id; SELECT * INTO s FROM public.life_settings WHERE id=1; IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status='running') THEN RAISE EXCEPTION 'Une activité est déjà en cours'; END IF;
IF _activity_id IS NOT NULL THEN SELECT * INTO a FROM public.activities WHERE activities.id=_activity_id AND character_id=cid AND status='planned' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Activité introuvable'; END IF; SELECT * INTO r FROM public.life_rules WHERE life_rules.id=a.type; IF t<a.start_time OR t>a.start_time+interval '30 minutes' THEN RAISE EXCEPTION 'Commencez pendant les 30 premières minutes du créneau'; END IF; a.start_time:=t; a.end_time:=t+r.duration_minutes*interval '1 minute';
ELSE SELECT * INTO r FROM public.life_rules WHERE life_rules.id=_type; IF NOT FOUND OR _type='course' THEN RAISE EXCEPTION 'Action inconnue'; END IF; a.type:=r.id; a.title:=r.title; a.location_id:=l.id; a.energy_cost:=r.energy_cost; a.energy_gain:=r.energy_gain; a.money_cost:=r.money_cost; a.progression_gain:=r.progression_gain; a.reward:=0; a.start_time:=t; a.end_time:=t+r.duration_minutes*interval '1 minute'; END IF;
IF a.location_id<>p.location_id OR NOT l.accessible OR NOT l.kind=ANY(r.allowed_kinds) THEN RAISE EXCEPTION 'Rejoignez le lieu de cette activité'; END IF;
IF a.type IN('study','course') AND NOT EXISTS(SELECT 1 FROM public.study_enrollments WHERE character_id=cid) THEN RAISE EXCEPTION 'Inscrivez-vous dans une filière'; END IF;
IF a.type='work' THEN SELECT j2.* INTO j FROM public.jobs j2 JOIN public.employments e ON e.job_id=j2.id WHERE e.character_id=cid; IF NOT FOUND OR j.location_id<>l.id THEN RAISE EXCEPTION 'Rejoignez votre emploi'; END IF; IF extract(isodow FROM t AT TIME ZONE 'UTC')>5 OR (t AT TIME ZONE 'UTC')::time<make_time(s.work_start,0,0) OR ((t+r.duration_minutes*interval '1 minute') AT TIME ZONE 'UTC')::time>make_time(s.work_end,0,0) THEN RAISE EXCEPTION 'Travail du lundi au vendredi, de 08:00 à 18:00'; END IF; IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND type='work' AND status IN('running','completed') AND (start_time AT TIME ZONE 'UTC')::date=(t AT TIME ZONE 'UTC')::date) THEN RAISE EXCEPTION 'Une vacation rémunérée par jour'; END IF; a.reward:=j.salary/s.paid_shifts_month; a.title:=j.title; END IF;
IF a.type='rest' AND NOT EXISTS(SELECT 1 FROM public.character_housing WHERE character_id=cid AND location_id=l.id) THEN RAISE EXCEPTION 'Rejoignez votre logement'; END IF;
IF a.type='transport' THEN SELECT * INTO target FROM public.locations WHERE locations.id=_target_location_id AND city_id=p.city_id AND accessible AND district_id IS NOT NULL; IF NOT FOUND OR target.id=l.id OR NOT EXISTS(SELECT 1 FROM public.districts WHERE districts.id=target.district_id AND available) THEN RAISE EXCEPTION 'Destination inaccessible'; END IF; a.target_location_id:=target.id; END IF;
IF c.energy<a.energy_cost THEN RAISE EXCEPTION 'Énergie insuffisante'; END IF; SELECT * INTO acc FROM public.accounts WHERE character_id=cid FOR UPDATE; IF NOT FOUND OR acc.balance<a.money_cost THEN RAISE EXCEPTION 'Solde insuffisant'; END IF;
IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status='planned' AND activities.id IS DISTINCT FROM _activity_id AND start_time<a.end_time AND end_time>a.start_time) THEN RAISE EXCEPTION 'Cette activité chevauche votre agenda'; END IF;
UPDATE public.characters SET energy=energy-a.energy_cost,updated_at=now() WHERE characters.id=cid; IF a.money_cost>0 THEN UPDATE public.accounts SET balance=balance-a.money_cost WHERE accounts.id=acc.id; INSERT INTO public.transactions(account_id,amount,label) VALUES(acc.id,-a.money_cost,a.title); END IF;
IF _activity_id IS NULL THEN INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,target_location_id,energy_cost,energy_gain,money_cost,reward,progression_gain,status) VALUES(cid,a.type,a.title,t,a.end_time,a.location_id,a.target_location_id,a.energy_cost,a.energy_gain,a.money_cost,a.reward,a.progression_gain,'running') RETURNING activities.id INTO id; ELSE UPDATE public.activities SET status='running',start_time=a.start_time,end_time=a.end_time,reward=a.reward WHERE activities.id=a.id RETURNING activities.id INTO id; END IF; RETURN id; END $$;
COMMENT ON FUNCTION public.start_life_activity(text,uuid,uuid) IS '30-minute arrival window; full configured duration required; one paid work shift per world day. All amounts and rewards are server-owned.';